def p(text, style="BodyCC"):
    return Paragraph(text, styles[style])


def rule():
    return HRFlowable(width="100%", thickness=.55, color=LINE, spaceBefore=3, spaceAfter=8)


def table(data, widths, header=True, padd=5, font=6.7):
    processed = []
    for ri, row in enumerate(data):
        processed.append([p(cell, "TableHead" if header and ri == 0 else "TableCC") for cell in row])
    t = Table(processed, colWidths=widths, repeatRows=1 if header else 0, hAlign="LEFT")
    commands = [
        ("VALIGN", (0,0), (-1,-1), "TOP"),
        ("LEFTPADDING", (0,0), (-1,-1), padd),
        ("RIGHTPADDING", (0,0), (-1,-1), padd),
        ("TOPPADDING", (0,0), (-1,-1), 4),
        ("BOTTOMPADDING", (0,0), (-1,-1), 4),
        ("GRID", (0,0), (-1,-1), .35, LINE),
        ("BACKGROUND", (0,0), (-1,0), INK),
    ]
    if len(data) > 2:
        for i in range(1, len(data)):
            if i % 2 == 0:
                commands.append(("BACKGROUND", (0,i), (-1,i), colors.HexColor("#F1F4F0")))
    t.setStyle(TableStyle(commands))
    return t


def footer(canvas, doc):
    canvas.saveState()
    w, h = A4
    canvas.setStrokeColor(LINE)
    canvas.setLineWidth(.4)
    canvas.line(doc.leftMargin, 15*mm, w-doc.rightMargin, 15*mm)
    canvas.setFont("DV", 6.7)
    canvas.setFillColor(colors.HexColor("#64766D"))
    canvas.drawString(doc.leftMargin, 10.5*mm, "КлиматКомфорт39 · маркетинговая аналитическая записка · срез 11.08.2026")
    canvas.drawRightString(w-doc.rightMargin, 10.5*mm, f"Страница {doc.page}")
    canvas.restoreState()


